import{_ as i,l as o,o as l,c as b,v as s,p as d,x as r,d as t,i as h,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"已实现 beta","description":"","frontmatter":{"title":"已实现 beta","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/realized-beta.md","filePath":"quant/realized-beta.md","lastUpdated":1789023840000}'),E={name:"quant/realized-beta.md"};function B(c,e,u,_,m,A){const n=o("Mermaid");return l(),b("div",null,[e[1]||(e[1]=s('<h1 id="已实现-beta" tabindex="-1">已实现 beta <a class="header-anchor" href="#已实现-beta" aria-label="Permalink to &quot;已实现 beta&quot;">​</a></h1><div class="epigraph"><p>把一天之内的协变差除以市场的已实现方差，得到当日的 $\\beta$；它测的是这一天共同波动里的暴露，不是三年日收益回归的平均斜率。</p><footer>—— Andersen, Bollerslev, Diebold and Wu 对已实现 beta 的经验与建模；二次协变差表述见 Barndorff-Nielsen and Shephard</footer></div><p><a href="/quant/realized-covariance">已实现协方差</a> 给出矩阵 \\(\\hat\\Sigma_t\\)。已实现 beta</p> \\[\\hat\\beta_{iM,t}=\\frac{\\widehat{\\langle X^i,X^M\\rangle}_t}{\\widehat{\\langle X^M\\rangle}_t} \\]<p>是当日对市场（或因子）的二次协变差比。Andersen、Bollerslev、Diebold 与 Wu 把它写成时变 \\(\\beta\\) 的测量，再对 \\(\\{\\hat\\beta_t\\}\\) 建模（持续、均值回复）。缺口是：<strong>分子分母的噪声与异步处理必须匹配</strong>，否则高频 \\(\\beta\\) 系统性偏小（Epps 在分子）。下一课刷新时间专门解决分母与分子的共同时钟。本课先钉对象：日度测量 vs 日频 OLS \\(\\beta\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日频 \\(\\beta\\) 来自 \\(R_{it}=\\alpha+\\beta R_{Mt}+\\varepsilon_{it}\\) 的月或年窗口，平均掉日内变异。已实现 \\(\\beta\\) 每个交易日一个读数，看见 \\(\\beta\\) 在公告日、危机日跳。问题是测量误差：\\(\\hat\\beta_t\\) 的误差来自 \\(\\hat\\Sigma\\) 的误差，薄股票、短会话噪声大，时序上看 \\(\\beta_t\\) 会抖。应用 Kalman 或 HAR 式平滑当状态，交易只用滤波后的 \\(\\beta\\)，接 <a href="/quant/state-space-kalman-smoother">状态空间</a> 纪律。</p><p>Fama–MacBeth 用时间序列 \\(\\beta\\) 进截面。用已实现 \\(\\beta\\) 的月平均进 FM，是用更好的测量减生成回归量噪声，但仍要 Shanken/HAC。对象仍是风险价格，不是宣称高频 \\(\\beta\\) 可交易。</p><h3 id="偏差清单" tabindex="-1">偏差清单 <a class="header-anchor" href="#偏差清单" aria-label="Permalink to &quot;偏差清单&quot;">​</a></h3><ul><li>异步：个股慢于指数期货，分子偏小，\\(\\hat\\beta\\lt 1\\) 的幻觉。</li><li>噪声：分母 TSRV、分子朴素，量纲乱。</li><li>隔夜：分子含隔夜、分母不含，或反过来。</li><li>跳跃：共跳让 \\(\\beta\\) 在新闻日飙升，连续 \\(\\beta\\) 应用跳稳健协方差。</li></ul><p><span class="marginnote">股指期货往往领先现货。用期货当 \\(M\\)、现货当 \\(i\\)，已实现 \\(\\beta\\) 含领先滞后。若对象是对冲现货，应允许滞后窗口或用 HY 滞后版，而不是强迫同期格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>构造。</strong> 同一同步规则下估 \\(\\langle i,M\\rangle\\) 与 \\(\\langle M\\rangle\\)。推荐：刷新时间 + 核，或五分钟 previous-tick 两边同一格。TSRV 只用于分母、分子用 HY，须在报告里当「混合估计」而不是标准已实现 \\(\\beta\\)。</p><p><strong>时序模型。</strong> \\(\\beta_{t+1}=c+\\rho\\beta_t+u_{t+1}\\) 或 HAR 式多尺度。测量方程 \\(\\hat\\beta_t=\\beta_t+v_t\\)，\\(v_t\\) 异方差（随 \\(IV\\) 与 \\(n\\)）。状态空间自然。样本外：用 \\(\\beta_{t|t-1}\\) 对冲次日，评估跟踪误差，不要用平滑 \\(\\beta_t\\)。</p><p><strong>截面。</strong> 月内日已实现 \\(\\beta\\) 平均，再当 FM 第一步。噪声仍在，Vasicek 收缩可向 1 拉，接 <a href="/quant/shrinkage-empirical-bayes">收缩</a>。薄股权重更大。</p><h3 id="与条件-capm" tabindex="-1">与条件 CAPM <a class="header-anchor" href="#与条件-capm" aria-label="Permalink to &quot;与条件 CAPM&quot;">​</a></h3><p>已实现 \\(\\beta\\) 是测量，不是检验。条件 CAPM 还要 \\(\\lambda_t\\)。高 \\(\\hat\\beta_t\\) 日的平均收益是否更高，是另一回归，HAC 与重叠照旧。不要把「\\(\\beta_t\\) 能预报」与「\\(\\beta_t\\) 测得准」混为一谈。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次协变差比是连续时间回归系数在一天上的积分版：若瞬时 \\(\\beta_u\\) 变化，已实现 \\(\\beta\\) 是以市场瞬时方差为权的平均。危机日 \\(\\sigma_M\\) 大，当天 \\(\\hat\\beta\\) 更反映危机暴露。机制解释为何已实现 \\(\\beta\\) 的时间变异大于日频滚动 \\(\\beta\\)（滚动还平均了许多天）。</p><p>Epps 机制：分子漏记共同波动，分母一元 RV 漏得少（只噪声），比值向下。同步修好分子后，\\(\\hat\\beta\\) 回升。这是执行对冲比时必须用已实现量而非日 \\(\\beta\\) 的理由之一——也是必须修 Epps 的理由。</p><p><span class="marginnote">对冲误差方差 \\(\\approx \\langle i\\rangle-\\langle i,M\\rangle^2/\\langle M\\rangle\\)，即已实现残差方差。报 \\(\\hat\\beta\\) 应同时报已实现 \\(R^2\\)。很低说明当天特异主导，对冲价值有限。</span></p><h3 id="到刷新时间的交接" tabindex="-1">到刷新时间的交接 <a class="header-anchor" href="#到刷新时间的交接" aria-label="Permalink to &quot;到刷新时间的交接&quot;">​</a></h3><p>刷新时间让所有腿在同一事件时钟上更新后再取收益，是多元核与已实现 \\(\\beta\\) 的标准前置。下一课写它丢掉什么信息、何时 HY 更省。本课只要求：\\(\\beta\\) 的两端同一时钟。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>半天市、熔断，\\(n\\) 小，\\(\\hat\\beta\\) 无对象。行业 ETF 对行业指数的 \\(\\beta\\) 近 1 噪声仍可观。用中点 \\(\\beta\\) 去对冲成交路径，执行滑点不在测量里。</p><p>工程：日频风控用五分钟已实现 \\(\\beta\\) 的 Kalman；研究用核。与日 OLS \\(\\beta\\) 并列。不要用未同步 tick \\(\\beta\\) 做盘中对冲。不要把已实现 \\(\\beta\\) 的 \\(t\\)（把日当独立）去检验 \\(\\beta=1\\)——须 HAC。下一课：刷新时间。</p>',26)),(l(),d(p,null,{default:r(()=>[h(n,{id:"mermaid-93",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E5%90%8C%E6%AD%A5%E4%B8%8B%E7%9A%84%20%CE%A3%CC%82%22%5D%20--%3E%20NUM%5B%22%E2%9F%A8i%2C%20M%E2%9F%A9%22%5D%0A%20%20S%20--%3E%20DEN%5B%22%E2%9F%A8M%E2%9F%A9%22%5D%0A%20%20NUM%20--%3E%20B%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%20%CE%B2_t%22%5D%0A%20%20DEN%20--%3E%20B%0A%20%20B%20--%3E%20SS%5B%22%E7%8A%B6%E6%80%81%E7%A9%BA%E9%97%B4%E5%B9%B3%E6%BB%91%2F%E6%BB%A4%E6%B3%A2%22%5D%0A%20%20EPPS%5B%22%E5%BC%82%E6%AD%A5%22%5D%20--%3E%20DOWN%5B%22%CE%B2%CC%82%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E5%B0%8F%22%5D%0A%20%20B%20--%3E%20FM%5B%22%E6%9C%88%E5%B9%B3%E5%9D%87%E8%BF%9B%20FM%20%2F%20%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"已实现 \\(\\beta\\) 是当日二次协变差比，测一天的暴露，不是长窗口 OLS \\(\\beta\\)。"),a("li",null,"分子分母须同一噪声与同步处理；异步使 \\(\\beta\\) 偏小。"),a("li",null,"\\(\\{\\hat\\beta_t\\}\\) 测量误差大，应用滤波再对冲；平滑不可交易。"),a("li",null,"共跳、隔夜、期货领先都改变对象，须声明。"),a("li",null,[t("出处：Andersen, Bollerslev, Diebold and Wu 关于已实现 beta；协变差理论见 Barndorff-Nielsen and Shephard, "),a("em",null,"Econometrica"),t(", 2004。")])],-1))])}const M=i(E,[["render",B]]);export{f as __pageData,M as default};
